mapper.select:
select s.* from project_schedule s
left join project_feedback f on s.id = f.schedule_id


        s.supervise_dep = #{query.depId,jdbcType=BIGINT}


        and f.has_problem = 1


        and s.status = #{query.status,jdbcType=VARCHAR}


        and s.type_id = #{query.typeId,jdbcType=BIGINT}


        and s.start_user = #{query.startUser,jdbcType=BIGINT}


        and s.create_time between #{query.period.begin,jdbcType=TIMESTAMP} and #{query.period.end,jdbcType=TIMESTAMP}


        and s.completion_time between #{query.completePeriod.begin,jdbcType=TIMESTAMP} and
        #{query.completePeriod.end,jdbcType=TIMESTAMP}


        and (s.project_name like concat('%',#{query.keyword,jdbcType=VARCHAR},'%')
        or s.party_b like concat('%',#{query.keyword,jdbcType=VARCHAR},'%')
        or s.project_num like concat('%',#{query.keyword,jdbcType=VARCHAR},'%')

            or

                s.supervise_users like concat('%',#{leader,jdbcType=VARCHAR},'%')



        )



        and s.`id` in

            #{id}




group by s.id order by s.create_time desc

SELECT DATE_FORMAT(t1.create_time,#{param.dateExp}) as period, COUNT(t1.id) as num FROM project_schedule t1
and t1.create_time >= #{param.period.begin}
and t1.create_time <= #{param.period.end}
GROUP BY DATE_FORMAT(t1.create_time,#{param.dateExp})

SELECT
t1.*
FROM
project_schedule t1
where
t1.tenant = #{tenant}

    and t1.update_time >= #{period.begin}


    and t1.update_time <= #{period.end}
